begin;
create function public.normalized_gallery(p_media jsonb,p_image text,p_original text,p_crop text) returns jsonb language plpgsql immutable set search_path=public as $$declare result jsonb:='[]';x jsonb;identity text;begin
 for x in select value from jsonb_array_elements(case when jsonb_typeof(p_media)='array' then p_media else '[]' end) loop
 identity:=coalesce(nullif(x->>'original_image',''),nullif(x->>'url',''));if identity is null then continue;end if;
 if not exists(select 1 from jsonb_array_elements(result) r where coalesce(r->>'original_image',r->>'url')=identity or r->>'url'=x->>'url') then result:=result||jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('url',coalesce(nullif(x->>'url',''),identity),'original_image',identity,'cropped_catalogue_image',coalesce(nullif(x->>'cropped_catalogue_image',''),x->>'url',identity),'caption',x->>'caption')));end if;end loop;
 if nullif(p_image,'') is not null and not exists(select 1 from jsonb_array_elements(result) r where p_image in(r->>'url',r->>'original_image',r->>'cropped_catalogue_image') or coalesce(p_original,p_image)=coalesce(r->>'original_image',r->>'url')) then result:=jsonb_build_array(jsonb_build_object('url',coalesce(nullif(p_crop,''),p_image),'original_image',coalesce(nullif(p_original,''),p_image),'cropped_catalogue_image',coalesce(nullif(p_crop,''),p_image)))||result;end if;
 return result;end$$;
update products set catalogue_media=normalized_gallery(catalogue_media,image_url,original_image,cropped_catalogue_image);
-- Preserve variant photos already visible to customers without requiring another upload.
do $$declare v record;begin for v in select product_id,image_url from product_variants where nullif(image_url,'') is not null loop update products set catalogue_media=normalized_gallery(catalogue_media||jsonb_build_array(jsonb_build_object('url',v.image_url,'original_image',v.image_url)),null,null,null) where id=v.product_id;end loop;end$$;
create function public.product_gallery_sync() returns trigger language plpgsql security definer set search_path=public as $$begin
 if tg_op='INSERT' or new.catalogue_media is not distinct from old.catalogue_media then new.catalogue_media:=normalized_gallery(new.catalogue_media,new.image_url,new.original_image,new.cropped_catalogue_image);else new.catalogue_media:=normalized_gallery(new.catalogue_media,null,null,null);end if;
 if jsonb_array_length(new.catalogue_media)>0 then new.image_url:=new.catalogue_media->0->>'url';new.original_image:=new.catalogue_media->0->>'original_image';new.cropped_catalogue_image:=new.catalogue_media->0->>'cropped_catalogue_image';else new.image_url:=null;new.original_image:=null;new.cropped_catalogue_image:=null;end if;return new;end$$;
create trigger product_gallery_sync before insert or update of catalogue_media,image_url,original_image,cropped_catalogue_image on products for each row execute function product_gallery_sync();
update products set catalogue_media=catalogue_media;
create function public.variant_gallery_sync() returns trigger language plpgsql security definer set search_path=public as $$begin if nullif(new.image_url,'') is not null then update products set catalogue_media=normalized_gallery(catalogue_media||jsonb_build_array(jsonb_build_object('url',new.image_url,'original_image',new.image_url)),null,null,null) where id=new.product_id and shop_id=new.shop_id;end if;return new;end$$;
create trigger variant_gallery_sync after insert or update of image_url on product_variants for each row execute function variant_gallery_sync();
-- Existing legacy URLs may be retained/reordered, while every newly supplied URL still needs an owned storage object.
create or replace function public.save_catalogue_media(p_product_id uuid,p_media jsonb,p_label_url text default null) returns void language plpgsql security definer set search_path=public as $$
declare s uuid:=current_shop_id();prior products;photo jsonb;u text;object_path text;clean jsonb;
begin
 if coalesce(current_workspace_role(),'')<>'admin' then raise exception 'Administrator access required';end if;
 select * into prior from products where id=p_product_id and shop_id=s for update;if not found then raise exception 'Product not found';end if;
 if jsonb_typeof(p_media) is distinct from 'array' or jsonb_array_length(p_media)>32 then raise exception 'Choose up to 32 photos';end if;
 for photo in select value from jsonb_array_elements(p_media||case when p_label_url is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('url',p_label_url)) end) loop
 if nullif(photo->>'url','') is null then raise exception 'Invalid catalogue media object';end if;
 for u in select x from unnest(array[photo->>'url',photo->>'original_image',photo->>'cropped_catalogue_image']) x where x is not null loop
 object_path:=split_part(u,'/storage/v1/object/public/catalogue-media/',2);
 if not (coalesce(u=prior.catalogue_label_url,false) or exists(select 1 from jsonb_array_elements(prior.catalogue_media) m where u in(m->>'url',m->>'original_image',m->>'cropped_catalogue_image'))) and (object_path not like s::text||'/'||p_product_id::text||'/%' or u !~ '^https?://' or not exists(select 1 from storage.objects where bucket_id='catalogue-media' and name=object_path)) then raise exception 'Invalid catalogue media object';end if;
 end loop;end loop;
 clean:=normalized_gallery(p_media,null,null,null);update products set catalogue_media=clean,catalogue_label_url=p_label_url,image_url=clean->0->>'url',original_image=clean->0->>'original_image',cropped_catalogue_image=clean->0->>'cropped_catalogue_image',updated_at=now() where id=p_product_id and shop_id=s;
end$$;
alter table customer_display_configs add column catalogue_appearance jsonb not null default '{"header_mode":"color","background_mode":"theme","overlay":0.92,"background_overlay":0.96,"blur":0,"focal_x":50,"focal_y":50}';
update workspace_backup_tables set columns=array_append(columns,'catalogue_appearance') where table_name='customer_display_configs';
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('catalogue-branding','catalogue-branding',true,12582912,array['image/jpeg','image/png','image/webp']);
create policy catalogue_branding_read on storage.objects for select to anon,authenticated using(bucket_id='catalogue-branding');
create policy catalogue_branding_admin on storage.objects for all to authenticated using(bucket_id='catalogue-branding' and (storage.foldername(name))[1]=current_shop_id()::text and current_workspace_role()='admin') with check(bucket_id='catalogue-branding' and (storage.foldername(name))[1]=current_shop_id()::text and current_workspace_role()='admin');
create function public.save_catalogue_appearance(p_values jsonb) returns void language plpgsql security definer set search_path=public as $$declare s uuid:=current_shop_id();v text;asset text;clean jsonb;begin
 if coalesce(current_workspace_role(),'')<>'admin' then raise exception 'Administrator access required';end if;
 if coalesce(p_values->>'header_mode','') not in('color','gradient','image') or coalesce(p_values->>'background_mode','') not in('theme','image') then raise exception 'Invalid appearance mode';end if;
 if coalesce((p_values->>'overlay')::numeric,0)<.90 or (p_values->>'overlay')::numeric>1 or coalesce((p_values->>'background_overlay')::numeric,0)<.95 or (p_values->>'background_overlay')::numeric>1 or coalesce((p_values->>'blur')::numeric,-1) not between 0 and 12 or coalesce((p_values->>'focal_x')::numeric,-1) not between 0 and 100 or coalesce((p_values->>'focal_y')::numeric,-1) not between 0 and 100 then raise exception 'Invalid appearance strength or position';end if;
 foreach asset in array array['header_url','header_original','background_url'] loop v:=nullif(p_values->>asset,'');if v is not null and(v !~ '^https?://' or split_part(v,'/storage/v1/object/public/catalogue-branding/',2) not like s::text||'/%' or not exists(select 1 from storage.objects where bucket_id='catalogue-branding' and name=split_part(v,'/storage/v1/object/public/catalogue-branding/',2))) then raise exception 'Invalid branding object';end if;end loop;
 if p_values->>'header_mode'='image' and nullif(p_values->>'header_url','') is null or p_values->>'background_mode'='image' and nullif(p_values->>'background_url','') is null then raise exception 'Upload an image before selecting image mode';end if;
 clean:=jsonb_build_object('header_mode',p_values->>'header_mode','background_mode',p_values->>'background_mode','header_url',nullif(p_values->>'header_url',''),'header_original',nullif(p_values->>'header_original',''),'background_url',nullif(p_values->>'background_url',''),'overlay',(p_values->>'overlay')::numeric,'background_overlay',(p_values->>'background_overlay')::numeric,'blur',(p_values->>'blur')::numeric,'focal_x',(p_values->>'focal_x')::numeric,'focal_y',(p_values->>'focal_y')::numeric);
 perform ensure_customer_display_config();update customer_display_configs set catalogue_appearance=clean,updated_at=now() where shop_id=s;insert into commercial_events(shop_id,entity_type,entity_id,action,details,performed_by) values(s,'shop',s,'catalogue_appearance',clean,auth.uid());end$$;
alter function get_commercial_catalogue(text) rename to get_commercial_catalogue_before_appearance;
revoke all on function get_commercial_catalogue_before_appearance(text) from public,anon,authenticated;
create function public.get_commercial_catalogue(p_token text default null) returns jsonb language plpgsql stable security definer set search_path=public as $$declare result jsonb;appearance jsonb;begin result:=get_commercial_catalogue_before_appearance(p_token);select catalogue_appearance into appearance from customer_display_configs where shop_id=case when p_token is null then current_shop_id() else (select shop_id from customer_display_configs where access_token=p_token and enabled) end;return result||jsonb_build_object('catalogue_appearance',appearance);end$$;
do $$declare d text;begin d:=pg_get_functiondef('workspace_storage_files(uuid)'::regprocedure);d:=replace(d,'''product-images'',''shop-logos'',''catalogue-media''','''catalogue-branding'',''product-images'',''shop-logos'',''catalogue-media''');execute d;end$$;
revoke all on function normalized_gallery(jsonb,text,text,text),product_gallery_sync(),variant_gallery_sync(),save_catalogue_appearance(jsonb),get_commercial_catalogue(text) from public,anon,authenticated;
grant execute on function save_catalogue_appearance(jsonb) to authenticated;grant execute on function get_commercial_catalogue(text) to anon,authenticated;
commit;
